import type { StorybookConfig } from '@storybook/html-vite';

const config: StorybookConfig = {
  stories: [
    '../stories/LuxuryCalibration.stories.ts',
    '../stories/RumContract.stories.ts',
    '../stories/ArticlePage.stories.ts',
    '../stories/ArticleReading.stories.ts',
    '../stories/Homepage.stories.ts',
    '../stories/CategoryPage.stories.ts',
    '../stories/SearchPage.stories.ts',
    '../stories/LiveStoryPage.stories.ts',
    '../stories/LinkInBioPage.stories.ts',
    '../stories/MediaPage.stories.ts',
    '../stories/StandalonePage.stories.ts',
    '../stories/partials/*.stories.ts',
    '../stories/react/**/*.stories.tsx'
  ],
  staticDirs: [
    { from: '../.cache/storybook-package-metadata', to: '/package-metadata' },
    { from: '../src/live-program/public', to: '/' },
    { from: '../stories/fixtures/article-reading', to: '/article-reading-fixtures' }
  ],
  addons: ['@chromatic-com/storybook', '@storybook/addon-vitest', '@storybook/addon-a11y', '@storybook/addon-docs'],
  framework: '@storybook/html-vite',
  async viteFinal(config) {
    return {
      ...config,
      assetsInclude: ['**/*.hbs']
    };
  }
};

export default config;

import assert from 'node:assert/strict';
import { execFile } from 'node:child_process';
import { createHash } from 'node:crypto';
import inspector from 'node:inspector';
import { mkdir, readFile, realpath, writeFile } from 'node:fs/promises';
import path from 'node:path';
import { fileURLToPath, pathToFileURL } from 'node:url';
import { promisify } from 'node:util';
import convert from 'ast-v8-to-istanbul';
import coverage from 'istanbul-lib-coverage';
import { parseAstAsync } from 'vitest/node';

const execute = promisify(execFile);
const script = fileURLToPath(import.meta.url);
const root = path.resolve(path.dirname(script), '..');
const hash = (value) => createHash('sha256').update(value).digest('hex');
const json = (file, value) => writeFile(file, `${JSON.stringify(value, null, 2)}\n`, { flag: 'wx' });

/** Bind native offsets to the actual source; unsupported transformations fail closed. */
export function verifyRuntimeSource({ source, runtime, url, native, parsed }) {
  assert.equal(native.url, url, 'Native coverage URL differs from the actual config');
  assert.equal(parsed.url, url, 'Debugger URL differs from the actual config');
  assert.equal(native.scriptId, parsed.scriptId, 'Native coverage and debugger script IDs differ');
  assert.ok(!parsed.sourceMapURL, 'A transformed config needs a separately qualified source map');
  assert.ok(runtime === source || runtime === `${source}\n\n//# sourceURL=${url}`,
    'Runtime is not the exact source with an optional Node sourceURL comment');
  const body = native.functions[0]?.ranges[0];
  assert.equal(body?.startOffset, 0, 'Native module range must start at zero');
  assert.equal(body?.endOffset, runtime.length, 'Native module range must bind the exact runtime text');
  return { sourceSHA256: hash(source), runtimeSHA256: hash(runtime), sourceChars: source.length,
    runtimeChars: runtime.length, suffix: runtime.slice(source.length) };
}

function projectOutput(config, observedDirectory, directory) {
  assert.equal(observedDirectory, directory, 'Config resolved the wrong dirname');
  assert.deepEqual(config?.test?.projects?.map((project) => project.test?.name), ['storybook', 'unit'],
    'Expected the actual Storybook and unit projects');
  const [storybook, unit] = config.test.projects;
  assert.equal(storybook.extends, true);
  assert.equal(storybook.test.browser.enabled, true);
  assert.equal(storybook.test.browser.headless, true);
  assert.deepEqual(storybook.test.browser.instances, [{ browser: 'chromium' }]);
  assert.deepEqual(storybook.test.setupFiles, ['.storybook/vitest.setup.ts']);
  assert.equal(storybook.plugins.length, 1);
  assert.equal(unit.extends, true);
  assert.equal(unit.test.environment, 'node');
  assert.ok(Array.isArray(unit.test.include) && unit.test.include.every((entry) => typeof entry === 'string'));
  return { names: config.test.projects.map((project) => project.test.name),
    browser: { enabled: storybook.test.browser.enabled, headless: storybook.test.browser.headless,
      instances: storybook.test.browser.instances }, setupFiles: storybook.test.setupFiles,
    unitEnvironment: unit.test.environment, unitInclude: unit.test.include,
    directory: observedDirectory, storybookConfigDir: path.join(observedDirectory, '.storybook') };
}

/** Each child evaluates the unchanged actual module in a declared host binding context. */
async function captureContext(mode, output) {
  assert.ok(mode === 'absent' || mode === 'provided', 'Unknown config binding context');
  const file = await realpath(path.join(root, 'vitest.config.ts'));
  const directory = path.dirname(file);
  const url = pathToFileURL(file).href;
  const source = await readFile(file, 'utf8');
  const probeLine = source.split('\n').findIndex((line) => line.includes('storybookTest({ configDir:'));
  assert.ok(probeLine >= 0, 'The actual Storybook config-directory observation site changed');
  if (mode === 'provided') globalThis.__dirname = directory;
  else assert.equal(typeof globalThis.__dirname, 'undefined', 'Absent context already has a dirname binding');

  const session = new inspector.Session();
  session.connect();
  const post = (method, parameters = {}) => new Promise((resolve, reject) =>
    session.post(method, parameters, (error, result) => error ? reject(error) : resolve(result)));
  const scripts = [];
  const observations = [];
  const pauseErrors = [];
  session.on('Debugger.scriptParsed', ({ params }) => { if (params.url === url) scripts.push(params); });
  session.on('Debugger.paused', ({ params }) => {
    const frame = params.callFrames[0];
    session.post('Debugger.evaluateOnCallFrame', { callFrameId: frame.callFrameId,
      expression: 'dirname', returnByValue: true }, (error, result) => {
      if (error || result.exceptionDetails) pauseErrors.push(String(error || result.exceptionDetails));
      else observations.push({ location: frame.location, value: result.result.value });
      session.post('Debugger.resume');
    });
  });
  try {
    await post('Debugger.enable');
    await post('Debugger.setBreakpointByUrl', { url, lineNumber: probeLine, columnNumber: 0 });
    await post('Profiler.enable');
    await post('Profiler.startPreciseCoverage', { callCount: true, detailed: true });
    const imported = await import(url);
    assert.deepEqual(pauseErrors, [], 'Could not observe the actual config binding');
    assert.equal(observations.length, 1, 'Expected one actual config-directory observation');
    const outputConfig = projectOutput(imported.default, observations[0].value, directory);
    assert.equal(await realpath(outputConfig.storybookConfigDir), path.join(directory, '.storybook'));
    const precise = await post('Profiler.takePreciseCoverage');
    await json(path.join(output, 'precise-raw.json'), precise);
    const matches = precise.result.filter((entry) => entry.url === url);
    assert.equal(matches.length, 1, 'Expected exactly one actual config coverage record');
    assert.equal(scripts.length, 1, 'Expected exactly one actual config debugger script');
    const native = matches[0];
    const { scriptSource: runtime } = await post('Debugger.getScriptSource', { scriptId: native.scriptId });
    assert.equal(await readFile(file, 'utf8'), source, 'Config source changed during collection');
    const identity = verifyRuntimeSource({ source, runtime, url, native, parsed: scripts[0] });
    await writeFile(path.join(output, 'runtime-source.txt'), runtime, { flag: 'wx' });
    const nativeCoverage = await convert({ code: runtime, ast: await parseAstAsync(runtime), coverage: native });
    const map = coverage.createCoverageMap(nativeCoverage);
    assert.deepEqual(map.files(), [file], 'Native remapping changed the source inventory');
    await json(path.join(output, 'coverage-final.json'), map.toJSON());
    const nativeAPIversions = { node: process.version, v8: process.versions.v8,
      astV8ToIstanbul: JSON.parse(await readFile(new URL('../package.json', import.meta.resolve('ast-v8-to-istanbul')), 'utf8')).version,
      vitest: JSON.parse(await readFile(new URL('../package.json', import.meta.resolve('vitest/node')), 'utf8')).version,
      istanbulLibCoverage: JSON.parse(await readFile(new URL('./package.json', import.meta.resolve('istanbul-lib-coverage')), 'utf8')).version };
    await json(path.join(output, 'context.json'), { schemaVersion: 1, mode, file, identity, output: outputConfig,
      observations, native, nativeAPIversions,
      context: mode === 'provided' ? 'Provided host/CJS-style dirname binding; not genuine CJS-loader acceptance'
        : 'Plain Node ESM with dirname binding absent',
      integration: 'Direct config evaluation; VITEST and VITEST_STORYBOOK flags cleared; no browser run' });
    await post('Profiler.stopPreciseCoverage');
  } finally {
    session.disconnect();
  }
}

/** Merge only identity-bound records with unchanged native maps. Never invent counters. */
export function aggregateContexts(absent, provided) {
  assert.equal(absent.context.mode, 'absent');
  assert.equal(provided.context.mode, 'provided');
  assert.equal(absent.context.file, provided.context.file, 'Config source paths differ');
  assert.deepEqual(absent.context.identity, provided.context.identity, 'Config source/runtime identities differ');
  assert.deepEqual(absent.context.output, provided.context.output, 'Binding contexts produced different config output');
  assert.deepEqual(absent.context.nativeAPIversions, provided.context.nativeAPIversions, 'Native producer versions differ');
  const file = absent.context.file;
  for (const record of [absent, provided]) assert.deepEqual(Object.keys(record.coverage), [file], 'Unexpected coverage source');
  for (const key of ['statementMap', 'fnMap', 'branchMap']) {
    assert.deepEqual(absent.coverage[file][key], provided.coverage[file][key], `Native ${key} differs`);
  }
  const result = coverage.createCoverageMap({});
  result.merge(absent.coverage);
  result.merge(provided.coverage);
  const merged = result.fileCoverageFor(file);
  for (const key of ['statementMap', 'fnMap', 'branchMap']) {
    assert.deepEqual(merged[key], absent.coverage[file][key], `Upstream aggregation changed ${key}`);
  }
  return result.toJSON();
}

export async function collectConfigCoverage(outputDirectory) {
  assert.ok(outputDirectory, 'An explicit new output directory is required');
  const output = path.resolve(outputDirectory);
  // Never overwrite an earlier measurement or remove someone else's evidence.
  await mkdir(output);
  const records = [];
  for (const mode of ['absent', 'provided']) {
    const destination = path.join(output, mode);
    await mkdir(destination);
    await execute(process.execPath, ['--enable-source-maps', '--experimental-strip-types', script,
      '--context', mode, '--output', destination], { cwd: root, timeout: 30_000,
      env: { ...process.env, VITEST: '', VITEST_STORYBOOK: '' } });
    records.push({ context: JSON.parse(await readFile(path.join(destination, 'context.json'), 'utf8')),
      coverage: JSON.parse(await readFile(path.join(destination, 'coverage-final.json'), 'utf8')) });
  }
  const merged = aggregateContexts(...records);
  await json(path.join(output, 'coverage-final.json'), merged);
  const context = records[0].context;
  const nativeMaps = Object.fromEntries(['statementMap', 'fnMap', 'branchMap'].map((key) => [key, merged[context.file][key]]));
  await json(path.join(output, 'summary.json'), { schemaVersion: 1, actualSource: context.file,
    sourceSHA256: context.identity.sourceSHA256, runtimeSHA256: context.identity.runtimeSHA256,
    identity: context.identity, nativeAPIversions: context.nativeAPIversions, observedConfig: context.output,
    mapIdentitySHA256: hash(JSON.stringify(nativeMaps)),
    contexts: records.map(({ context: item }) => ({ mode: item.mode, label: item.context,
      context: `${item.mode}/context.json`, precise: `${item.mode}/precise-raw.json`,
      runtime: `${item.mode}/runtime-source.txt`, coverage: `${item.mode}/coverage-final.json` })),
    mapsIdentical: true, producer: 'Node inspector precise coverage + ast-v8-to-istanbul',
    aggregation: 'istanbul-lib-coverage', scope: 'Config file only; not full-source or CJS-loader acceptance' });
  return { outputDirectory: output, coverageFile: path.join(output, 'coverage-final.json') };
}

if (process.argv[1] && await realpath(process.argv[1]) === script) {
  try {
    const args = process.argv.slice(2);
    if (args.length === 2 && args[0] === '--output') await collectConfigCoverage(args[1]);
    else if (args.length === 4 && args[0] === '--context' && args[2] === '--output') await captureContext(args[1], args[3]);
    else throw new Error('Usage: node scripts/collect-config-coverage.mjs --output NEW_DIRECTORY');
  } catch (error) {
    console.error(error.message);
    process.exitCode = 1;
  }
}

import assert from 'node:assert/strict';
import { execFile } from 'node:child_process';
import { mkdtemp, readFile, rm } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { promisify } from 'node:util';
import { afterAll, beforeAll, describe, expect, it } from 'vitest';
import { aggregateContexts, collectConfigCoverage, verifyRuntimeSource } from './collect-config-coverage.mjs';

const execute = promisify(execFile);
const script = fileURLToPath(new URL('./collect-config-coverage.mjs', import.meta.url));
let directory;
let output;
let records;
const readJSON = async (file) => JSON.parse(await readFile(file, 'utf8'));

beforeAll(async () => {
  directory = await mkdtemp(path.join(tmpdir(), 'brokaw-native-config-'));
  output = path.join(directory, 'measurement');
  await collectConfigCoverage(output);
  records = await Promise.all(['absent', 'provided'].map(async (mode) => ({
    context: await readJSON(path.join(output, mode, 'context.json')),
    coverage: await readJSON(path.join(output, mode, 'coverage-final.json')),
  })));
}, 30_000);

afterAll(async () => { if (directory) await rm(directory, { recursive: true, force: true }); });

describe('actual config native coverage producer', () => {
  it('observes both real binding states with identical configuration and source identity', async () => {
    const [absent, provided] = records;
    expect(absent.context.mode).toBe('absent');
    expect(provided.context.mode).toBe('provided');
    expect(provided.context.context).toContain('not genuine CJS-loader acceptance');
    expect(absent.context.output).toEqual(provided.context.output);
    expect(absent.context.output.names).toEqual(['storybook', 'unit']);
    expect(absent.context.output.storybookConfigDir).toBe(path.join(path.dirname(absent.context.file), '.storybook'));
    expect(absent.context.identity).toEqual(provided.context.identity);
    expect(absent.context.identity.sourceSHA256).toMatch(/^[a-f0-9]{64}$/);
    for (const record of records) {
      const mode = record.context.mode;
      const source = await readFile(record.context.file, 'utf8');
      const runtime = await readFile(path.join(output, mode, 'runtime-source.txt'), 'utf8');
      const precise = await readJSON(path.join(output, mode, 'precise-raw.json'));
      expect(precise.result).toContainEqual(record.context.native);
      expect(runtime).toBe(source + record.context.identity.suffix);
      expect(record.context.native.functions[0].ranges[0].endOffset).toBe(runtime.length);
    }
  });

  it('retains complementary native branch outcomes and unchanged maps through official aggregation', async () => {
    const [absent, provided] = records;
    const file = absent.context.file;
    expect(absent.coverage[file].b).toEqual({ 0: [0, 1] });
    expect(provided.coverage[file].b).toEqual({ 0: [1, 0] });
    const merged = await readJSON(path.join(output, 'coverage-final.json'));
    expect(Object.keys(merged)).toEqual([file]);
    for (const key of ['statementMap', 'fnMap', 'branchMap']) {
      expect(merged[file][key]).toEqual(absent.coverage[file][key]);
      expect(merged[file][key]).toEqual(provided.coverage[file][key]);
    }
    const collection = await readJSON(path.join(output, 'summary.json'));
    expect(collection.mapsIdentical).toBe(true);
    expect(collection.scope).toContain('Config file only');
    expect(collection.actualSource).toBe(file);
    expect(collection.nativeAPIversions.astV8ToIstanbul).toBe('1.0.0');
    expect(collection.nativeAPIversions.istanbulLibCoverage).toBe('3.2.2');
    expect(collection.mapIdentitySHA256).toMatch(/^[a-f0-9]{64}$/);
  });

  it('does not overwrite retained evidence or accept an implicit destination', async () => {
    await expect(collectConfigCoverage()).rejects.toThrow('explicit new output directory');
    await expect(collectConfigCoverage(output)).rejects.toMatchObject({ code: 'EEXIST' });
    expect((await readJSON(path.join(output, 'summary.json'))).mapsIdentical).toBe(true);
  });

  it.each([
    ['source hash', (record) => { record.context.identity.sourceSHA256 = 'changed'; }],
    ['runtime hash', (record) => { record.context.identity.runtimeSHA256 = 'changed'; }],
    ['source path', (record) => { record.context.file += '.different'; }],
    ['actual config output', (record) => { record.context.output.directory += '/wrong'; }],
    ['native map', (record) => { record.coverage[record.context.file].branchMap = {}; }],
  ])('rejects %s corruption instead of combining incompatible records', (_name, corrupt) => {
    // Corrupt metadata/maps of real producer records, never invent passing counters.
    const [absent, provided] = structuredClone(records);
    corrupt(provided);
    expect(() => aggregateContexts(absent, provided)).toThrow();
  });

  it('rejects unproved runtime transformations, external mappings and mismatched script identity', async () => {
    const context = records[0].context;
    const source = await readFile(context.file, 'utf8');
    const runtime = await readFile(path.join(output, 'absent', 'runtime-source.txt'), 'utf8');
    const actual = { source, runtime, url: context.native.url, native: context.native,
      parsed: { url: context.native.url, scriptId: context.native.scriptId } };
    expect(verifyRuntimeSource(actual)).toEqual(context.identity);
    expect(() => verifyRuntimeSource({ ...actual, runtime: `${runtime}\nchanged` })).toThrow('exact source');
    expect(() => verifyRuntimeSource({ ...actual, parsed: { ...actual.parsed, sourceMapURL: 'unproved.map' } })).toThrow('qualified source map');
    expect(() => verifyRuntimeSource({ ...actual, parsed: { ...actual.parsed, scriptId: 'wrong-script' } })).toThrow('script IDs differ');
    assert.equal(context.identity.sourceChars, source.length);
  });

  it('fails unknown CLI arguments and private binding modes without producing a final report', async () => {
    await expect(execute(process.execPath, [script, '--unknown'])).rejects.toMatchObject({
      stderr: expect.stringContaining('Usage:'),
    });
    await expect(execute(process.execPath, [script, '--context', 'invalid', '--output', directory])).rejects.toMatchObject({
      stderr: expect.stringContaining('Unknown config binding context'),
    });
  });
});

import { createHash } from 'node:crypto';
import { mkdir, readFile, realpath, rename, rm, writeFile } from 'node:fs/promises';
import { dirname, join, resolve } from 'node:path';
import { fileURLToPath, pathToFileURL } from 'node:url';
import { isDeepStrictEqual } from 'node:util';
import coverage from 'istanbul-lib-coverage';

const root = fileURLToPath(new URL('../', import.meta.url));
const readJson = async (filename) => JSON.parse(await readFile(filename, 'utf8'));

export async function mergeNativeCoverage({ applicationReport, configurationDirectory, output }) {
  const destination = resolve(output);
  const supplementalReport = join(configurationDirectory, 'coverage-final.json');
  const summaryPath = join(configurationDirectory, 'summary.json');
  const configSource = await realpath(join(root, 'vitest.config.ts'));
  if ([applicationReport, supplementalReport, summaryPath, configSource].some((path) => resolve(path) === destination)) {
    throw new Error('Native coverage output must not replace an input or the measured configuration.');
  }
  await rm(destination, { force: true });

  const [application, supplemental, summary, source] = await Promise.all([
    readJson(applicationReport), readJson(supplementalReport), readJson(summaryPath), readFile(configSource),
  ]);
  if (summary.actualSource !== configSource || summary.sourceSHA256 !== createHash('sha256').update(source).digest('hex')) {
    throw new Error('Supplemental native coverage does not match the actual configuration source.');
  }

  const applicationMap = coverage.createCoverageMap(application);
  const supplementalMap = coverage.createCoverageMap(supplemental);
  if (!applicationMap.files().length) throw new Error('Application native coverage must not be empty.');
  if (supplementalMap.files().length !== 1 || supplementalMap.files()[0] !== configSource) {
    throw new Error('Supplemental native coverage must contain only the actual configuration file.');
  }
  if (applicationMap.files().some((filename) => supplementalMap.files().includes(filename))) {
    throw new Error('Native coverage inputs overlap; supplemental counters cannot replace application measurements.');
  }

  // Upstream aggregation joins genuinely disjoint native file records. Preserve
  // each producer's maps and counters exactly; do not reinterpret either format.
  const merged = coverage.createCoverageMap(structuredClone(application));
  merged.merge(structuredClone(supplemental));
  for (const [filename, record] of Object.entries({ ...application, ...supplemental })) {
    if (!isDeepStrictEqual(merged.fileCoverageFor(filename).toJSON(), record)) {
      throw new Error(`Upstream aggregation changed the native record for ${filename}.`);
    }
  }

  await mkdir(dirname(destination), { recursive: true });
  const temporary = `${destination}.${process.pid}.tmp`;
  await writeFile(temporary, `${JSON.stringify(merged.toJSON())}\n`);
  await rename(temporary, destination);
}

export function coverageArguments(args) {
  const names = ['--application', '--configuration', '--output'];
  if (args.length !== 6 || args.some((value, index) => index % 2 === 0 && !names.includes(value))) {
    throw new Error('Usage: merge-native-coverage.mjs --application REPORT --configuration DIRECTORY --output REPORT');
  }
  const values = new Map([0, 2, 4].map((index) => [args[index], args[index + 1]]));
  if (values.size !== 3 || [...values.values()].some((value) => !value || value.startsWith('--'))) {
    throw new Error('Three distinct native coverage paths are required.');
  }
  return {
    applicationReport: values.get('--application'),
    configurationDirectory: values.get('--configuration'),
    output: values.get('--output'),
  };
}

if (process.argv[1] && import.meta.url === pathToFileURL(resolve(process.argv[1])).href) {
  await mergeNativeCoverage(coverageArguments(process.argv.slice(2)));
}

import { execFile } from 'node:child_process';
import { copyFile, mkdtemp, mkdir, readFile, rm, writeFile } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';
import { promisify } from 'node:util';
import { afterAll, beforeAll, describe, expect, it } from 'vitest';
import { collectConfigCoverage } from './collect-config-coverage.mjs';
import { coverageArguments, mergeNativeCoverage } from './merge-native-coverage.mjs';

const execute = promisify(execFile);
const root = dirname(dirname(fileURLToPath(import.meta.url)));
const readJson = async (filename) => JSON.parse(await readFile(filename, 'utf8'));
let directory;
let applicationReport;
let configurationDirectory;

beforeAll(async () => {
  directory = await mkdtemp(join(tmpdir(), 'brokaw-native-merge-'));
  configurationDirectory = join(directory, 'config');
  await collectConfigCoverage(configurationDirectory);
  const applicationDirectory = join(directory, 'application');
  // Obtain the other native input by executing a real existing boundary test.
  // These temporary native reports are test inputs, never acceptance evidence.
  await execute(process.execPath, [join(root, 'node_modules/vitest/vitest.mjs'), 'run',
    '--project', 'unit', 'src/utils/sofascore.test.ts', '--coverage.enabled=true',
    '--coverage.provider=v8', '--coverage.include=src/utils/sofascore.ts',
    '--coverage.reporter=json', `--coverage.reportsDirectory=${applicationDirectory}`,
  ], { cwd: root, timeout: 30_000 });
  applicationReport = join(applicationDirectory, 'coverage-final.json');
}, 45_000);

afterAll(async () => { if (directory) await rm(directory, { recursive: true, force: true }); });

const options = (output) => ({ applicationReport, configurationDirectory, output });

describe('disjoint native coverage aggregation', () => {
  it('preserves both real producers maps and counters without rewriting either input', async () => {
    const supplementalReport = join(configurationDirectory, 'coverage-final.json');
