    url: `/story-${id}`,
    title: `Article ${id}`,
    categories: [],
    featured: opts.featured,
    publishedAt: opts.publishedAt ?? `2026-03-${String((id % 9) + 1).padStart(2, '0')}T09:00:00.000Z`,
    updatedAt: opts.publishedAt ?? `2026-03-${String((id % 9) + 1).padStart(2, '0')}T09:00:00.000Z`
  };
